entries[459086] = { ["name"] = "Relikt der Sucher aus alten Zeiten", ["text"] = "100 Meter Reichweite\nSofort\nWenn Brann ' Sammelwerkzeuge ' einsetzt, besteht eine Chance von 35%, ein mächtiges Artefakt freizulegen, das Eurer Gruppe einen mächtigen Segen gewährt.\n\nSammelwerkzeuge\nBrann setzt seine Sammelwerkzeuge ein, um Spielercharakteren zu helfen, zusätzliches Gold, Erz, Leder, zusätzliche Kräuter, Fische und Schätze zu finden." }
