entries[459092] = { ["name"] = "Lebloses Relikt der Nekrotischen Fäulnis", ["text"] = "Sofort\nDer Götze benutzt unheilige Energie, um tödlichen Schaden bei Spielercharakteren zu verhindern und heilt sie stattdessen um einen Betrag, der 100 % ihrer maximalen Gesundheit entspricht, und verwandelt sie in Untote.\n\nSolange sie untot sind, können sie nicht geheilt werden, verlieren alle 1 Sek. 11 % ihrer maximalen Gesundheit, und ihr Schaden und ihre Heilung ist um 8 % erhöht." }
