entries[459134] = { ["name"] = "Reliktblut von Zekvir", ["text"] = "Sofort\nAn zufälligen Zeitpunkten während des Kampfes wird eine Blutbestie erscheinen, die sich an Brann festsetzt und in der Nähe von Spielercharakteren regelmäßig Stücke von sich selbst schleudert. Spielercharaktere, die über diese Stücke laufen, erhalten ' Blutbefleckter Segen '.\n\nBlutbefleckter Segen\nVerursachter Schaden und hervorgerufene Heilung um 2% und maximale Gesundheit um 5% verringert. Hält 1 Min. lang an." }
