entries[459805] = { ["name"] = "Klagender Pfeil", ["text"] = "Sofort\nNach Eurem 20. Einsatz von 'Windpfeil' wird Euer nächster 'Gezielter Schuss' zu 'Klagender Pfeil'.\n\nKlagender Pfeil\nVerschießt einen verzauberten Pfeil, der Eurem Ziel (360% der Angriffskraft) Schattenschaden sowie allen Gegnern innerhalb von 8 Metern um das Ziel zusätzlich (112.5% der Angriffskraft) Schattenschaden zufügt. Ziele, die keine Spielercharaktere sind und von 'Klagender Pfeil' getroffen werden, werden beim Zaubern unterbrochen und 3 Sek. lang zum Schweigen gebracht. [ Bereitschaft : 'Klagender Pfeil' schließt die Abklingzeit von 'Schnellfeuer' ab und erzeugt 2 Aufladungen von 'Gezielter Schuss' ] [ Sperrfeuer des Windläufers : 'Klagender Pfeil' verschießt 5 Windpfeile auf Euer Primärziel sowie 10 Windpfeile, die auf getroffene Sekundärziele aufgeteilt werden und jeweils (20% der Angriffskraft) körperlichen Schaden verursachen ]" }
entries[459806] = { ["name"] = "Klagender Pfeil", ["text"] = "Nach Eurem 20. Einsatz von 'Windpfeil' wird Euer nächster 'Gezielter Schuss' zu 'Klagender Pfeil'.\n\nKlagender Pfeil\nVerschießt einen verzauberten Pfeil, der Eurem Ziel (360% der Angriffskraft) Schattenschaden sowie allen Gegnern innerhalb von 8 Metern um das Ziel zusätzlich (112.5% der Angriffskraft) Schattenschaden zufügt. Ziele, die keine Spielercharaktere sind und von 'Klagender Pfeil' getroffen werden, werden beim Zaubern unterbrochen und 3 Sek. lang zum Schweigen gebracht. [ Bereitschaft : 'Klagender Pfeil' schließt die Abklingzeit von 'Schnellfeuer' ab und erzeugt 2 Aufladungen von 'Gezielter Schuss' ] [ Sperrfeuer des Windläufers : 'Klagender Pfeil' verschießt 5 Windpfeile auf Euer Primärziel sowie 10 Windpfeile, die auf getroffene Sekundärziele aufgeteilt werden und jeweils (20% der Angriffskraft) körperlichen Schaden verursachen ]" }
