entries[460156] = { ["name"] = "Schnellstart", ["text"] = "Wirken in 1.5 sek.\nSobald alle Mechadrohnen der Düsternisverschmolzenen besiegt wurden, versucht die Große M.A.M.A., ihre erschöpfte Batterie mit externer Energie zu versorgen. Durch diesen Prozess erleidet sie 200% mehr Schaden und entfesselt 12 Sek. lang alle 1.5 Sek. Energieladungen. Jede Energieladung fügt allen Spielercharakteren 1745604 Naturschaden zu.\n\nWenn die Batterie wieder voll aufgeladen ist, verursacht Große M.A.M.A. eine ' Exzessive Elektrifizierung '." }
entries[460158] = { ["name"] = "Schnellstart", ["text"] = "Sofort\nSobald alle Mechadrohnen der Düsternisverschmolzenen besiegt wurden, versucht die Große M.A.M.A., ihre erschöpfte Batterie mit externer Energie zu versorgen. Durch diesen Prozess erleidet sie 200% mehr Schaden und entfesselt 12 Sek. lang alle 1.5 Sek. Energieladungen. Jede Energieladung fügt allen Spielercharakteren 1745604 Naturschaden zu.\n\nWenn die Batterie wieder voll aufgeladen ist, verursacht Große M.A.M.A. eine ' Exzessive Elektrifizierung '." }
entries[460159] = { ["name"] = "E.M.P.-Mörser", ["text"] = "100 Meter Reichweite\nWirken in 2 sek.\nGroße M.A.M.A. feuert ein E.M.P.-Geschoss auf einen Spielercharakter in der Nähe ab, das beim Einschlag 3 Naturschaden verursacht sowie Spielercharakteren in einem Umkreis von 10 Metern 10 Sek. lang alle 1 Sek. 3 zusätzlichen Naturschaden zufügt. Bei Entfernung betäubt ein E.M.P. alle Drohnen in einem Umkreis von 10 Metern für 6 Sek." }
entries[460161] = { ["name"] = "Phasenklingen", ["text"] = "Unbegrenzte Reichweite\nSofort\nSikran markiert Spielcharaktere, springt zu den einzelnen markierten Zielen und fügt jedem auf seinem Weg 3741605 körperlichen Schaden zu.\n\nZusätzlich wird die erhaltene Heilung betroffener Spielercharaktere um 50% verringert und sie erleiden 20 Sek. lang alle 2 Sek. 474896 zusätzlichen Schattenschaden.\n\nMarkierte Ziele hinterlassen ein ' Kosmisches Simulakrum ', wenn sie getroffen werden." }
entries[460162] = { ["name"] = "Arkane Stasis" }
entries[460163] = { ["name"] = "E.M.P.-Mörser", ["text"] = "100 Meter Reichweite\nSofort\nGroße M.A.M.A. feuert ein E.M.P.-Geschoss auf einen Spielercharakter in der Nähe ab, das beim Einschlag 3 Naturschaden verursacht sowie Spielercharakteren in einem Umkreis von 10 Metern 10 Sek. lang alle 1 Sek. 3 zusätzlichen Naturschaden zufügt. Bei Entfernung betäubt ein E.M.P. alle Drohnen in einem Umkreis von 10 Metern für 6 Sek." }
entries[460164] = { ["name"] = "Widerwärtiger Ausstoß", ["text"] = "Sofort\nDer einarmige Bandit stößt 1.5 Sek. lang alle 0.5 Sek. rußige Abgase auf alle Spielercharaktere aus. Jeder Schwall absorbiert die nächsten 1429682 eintreffende Heilung.\n\nSolange dieser Effekt anhält, verursacht er alle 1 Sek. 120745 Schattenschaden und verringert die Bewegungsgeschwindigkeit um 15% pro Anwendung." }
