entries[460427] = { ["name"] = "Gewinnlinie", ["text"] = "300 Meter Reichweite\nSofort\nDer einarmige Bandit rollt einen gewaltigen Casinojeton auf Spielercharaktere zu, durch den alle in seiner Bahn ' Zerquetscht! ' werden. Spielercharaktere können in der Nähe seiner Bahn stehen, um ' Glücksroller! ' zu werden.\n\nWenn der Jeton sein Ziel erreicht, kippt er um und fügt Spielercharakteren innerhalb von 15 Metern 12577630 Naturschaden sowie zusätzlich allen Spielercharakteren 1211645 Naturschaden zu.\n\nSpielercharaktere können diese Jetons zurückrollen, um sie zu zerstören." }
entries[460429] = { ["name"] = "Maschinenöl" }
entries[460430] = { ["name"] = "Zerquetscht!", ["text"] = "300 Meter Reichweite\nSofort\nSpielercharaktere, die von der Marke überrollt werden, werden darunter zermalmt, erleiden 6708070 körperlichen Schaden und werden für 8 Sek. betäubt." }
entries[460436] = { ["name"] = "Springflut", ["text"] = "40 Meter Reichweite\nSofort 5 sek. Abklingzeit\nHeilende Wasser fließen über ein verbündetes Ziel hinweg, heilen es um 183476 Gesundheit sowie zusätzlich im Verlauf von 18 Sek. um 0 Gesundheit." }
entries[460438] = { ["name"] = "Heilende Woge", ["text"] = "40 Meter Reichweite\nWirken in 1.5 sek.\nEine schnelle Woge heilender Energie, die 338724 Gesundheit eines verbündeten Ziels wiederherstellt." }
entries[460439] = { ["name"] = "Kettenheilung", ["text"] = "3% von Grundmana 40 Meter Reichweite\nWirken in 2.4 sek.\nHeilt das verbündete Ziel um 191778 Gesundheit und springt dann bis zu 15 Meter auf die 3 am schwersten verletzten Verbündeten in der Nähe über, um sie zu heilen. Mit jedem Sprung verringert sich die Heilung um 30%." }
entries[460443] = { ["name"] = "Blitzschlag", ["text"] = "40 Meter Reichweite\nWirken in 1.4 sek.\nSchleudert einen Blitzschlag auf das Ziel, der 276387 Naturschaden verursacht.\n\nErzeugt 8 Mahlstrom." }
entries[460444] = { ["name"] = "Glücksroller!", ["text"] = "Sofort\nSpielercharaktere werden zu Glücksrollern, was 15 Sek. lang ihren verursachten Schaden und ihre hervorgerufene Heilung um 10% und ihre Bewegungsgeschwindigkeit um 30% erhöht." }
entries[460448] = { ["name"] = "Unheilige Verseuchung", ["text"] = "'Dunkle Transformation' umgibt Euren Ghul für 6 Sek. mit einem üblen Schwarm aus Insekten, die alle Gegner in der Nähe stechen und sie mit der Virulenten Seuche sowie einer unheiligen Krankheit infizieren, die im Verlauf von 14 Sek. (27.832% der Angriffskraft) Schaden verursacht. Bis zu 4-mal stapelbar." }
entries[460449] = { ["name"] = "Bodenausbruch" }
entries[460452] = { ["name"] = "Kosmisches Simulakrum" }
entries[460453] = { ["name"] = "Kosmisches Simulakrum" }
entries[460454] = { ["name"] = "Wartungsschock", ["text"] = "Sofort\nGroße M.A.M.A. lädt alle besiegten Drohnen in der Nähe wieder auf, indem sie pro Drohne (-- 20)) Energie verbraucht, um sie wieder voll einsatzbereit zu machen. Der Schock lässt elektrische Funken sprühen, die bei Kontakt Spielercharakteren 10 Naturschaden zufügen." }
entries[460463] = { ["name"] = "V.O.G.E.L. aktivieren" }
entries[460467] = { ["name"] = "V.O.G.E.L. deaktivieren", ["text"] = "30 Meter Reichweite\nSofort" }
entries[460468] = { ["name"] = "Hand der Provokation", ["text"] = "40 Meter Reichweite\nSofort 1.5 sek. Abklingzeit\nVerspottet das Ziel, damit es Euch angreift, hat aber keinerlei Effekt, wenn das Ziel Euch bereits angreift." }
entries[460469] = { ["name"] = "Energiegeladene Sturmkrähenfeder", ["text"] = "15 Meter Reichweite\nSofort 1.5 min Abklingzeit\nHält die Feder für [1.0][1] Sek. hoch, um mit der Macht des Sturms zuzuschlagen, der auf den Zielort niedergeht und ( 1 * 3166 ) Naturschaden verursacht, die auf Gegner in der Nähe aufgeteilt werden." }
entries[460472] = { ["name"] = "Der Volltreffer", ["text"] = "100 Meter Reichweite\nWirken in 2.5 sek. 3 sek. Abklingzeit\nDer einarmige Bandit schmettert mit seinem großen Arm auf den Boden, fügt seinem Ziel so 50310521 körperlichen Schaden zu und lässt es 30 Sek. lang 750% mehr Schaden durch ' Der Volltreffer ' erleiden. Dieser Effekt ist stapelbar.\n\nZusätzlich hinterlässt ' Der Volltreffer ' ein ' Schockfeld '." }
entries[460474] = { ["name"] = "Schockfeld", ["text"] = "100 Meter Reichweite\nSofort\nSpielercharaktere, die im elektrischen Feld stehen, erleiden 150% mehr Schaden und alle 1 Sek. 838509 Naturschaden." }
entries[460475] = { ["name"] = "Pyroschlag", ["text"] = "40 Meter Reichweite\nSofort\nSchleudert einen immensen feurigen Felsen, der (150% der Zaubermacht) Feuerschaden verursacht." }
entries[460476] = { ["name"] = "Flammenstoß", ["text"] = "40 Meter Reichweite\nWirken in 3.5 sek.\nLässt eine Feuersäule niedergehen, die alle Gegner im Bereich verbrennt und ihnen so (60% der Zaubermacht) Feuerschaden zufügt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu." }
entries[460478] = { ["name"] = "Windlaufen", ["text"] = "Teilt Euch für 15 Sek. in 3 Elementargeister auf, die jeweils 40% des normalen Schadens und der Heilung verursachen.\n\nIhr kontrolliert den Sturmgeist direkt, während der Erd- und der Feuergeist Eure Angriffe bei Gegnern in der Nähe imitieren.\n\nWährend die Geister aktiv sind, führt der erneute Einsatz von 'Sturm, Erde und Feuer' dazu, dass die Geister sich auf Euer Ziel fixieren." }
entries[460482] = { ["name"] = "Überragender Wildtierköder", ["text"] = "2 Meter ReichweiteWirken in 2 sek. 1 min Abklingzeit\nPlatziert den Köder und lockt eine hochkarätige scheue Kreatur aus ihrem Versteck.\n\nKann nur in der Grollenden Einöde in den Schallenden Tiefen eingesetzt werden." }
entries[460484] = { ["name"] = "Zutaten werfen", ["text"] = "Sofort" }
entries[460485] = { ["name"] = "Chistoß", ["text"] = "Ca. 1.5 Procs pro Minute\nWindläufer, Nebelwirker\nEure Schaden verursachenden Zauber und Fähigkeiten haben eine Chance, 'Chistoß' zu aktivieren, wodurch Ihr einen Schwall Chienergie bis zu 40 Meter vorwärts schleudert, der auf seinem Weg allen Gegnern (280% der Angriffskraft) Naturschaden zufügt und den Mönch sowie alle Verbündeten um (220% der Angriffskraft) Gesundheit heilt. Heilung und Schaden bei Zielen über 5 Ziele hinaus verringert.\n\nBraumeister\nEure Schaden verursachenden Zauber und Fähigkeiten haben eine Chance, 'Chistoß' zu aktivieren, wodurch Ihr einen Schwall Chienergie bis zu 40 Meter vorwärts schleudert, der auf seinem Weg allen Gegnern (280% der Angriffskraft) Naturschaden zufügt und den Mönch sowie alle Verbündeten um (220% der Angriffskraft) Gesundheit heilt. Heilung und Schaden bei Zielen über 5 Ziele hinaus verringert.\n\nBeim Einsatz von 'Chistoß' sind Vermeidungsmechaniken weiterhin aktiv." }
entries[460489] = { ["name"] = "Wartungsschock", ["text"] = "100 Meter Reichweite\nSofort\nGroße M.A.M.A. lädt alle besiegten Drohnen in der Nähe wieder auf, indem sie pro Drohne (-- 20)) Energie verbraucht, um sie wieder voll einsatzbereit zu machen. Der Schock lässt elektrische Funken sprühen, die bei Kontakt Spielercharakteren 10 Naturschaden zufügen." }
entries[460490] = { ["name"] = "Chistoß", ["text"] = "Sofort\nEure Schaden verursachenden Zauber und Fähigkeiten haben eine Chance, 'Chistoß' zu aktivieren, wodurch Ihr einen Schwall Chienergie bis zu 40 Meter vorwärts schleudert, der auf seinem Weg allen Gegnern (280% der Angriffskraft) Naturschaden zufügt und den Mönch sowie alle Verbündeten um (220% der Angriffskraft) Gesundheit heilt. Heilung und Schaden bei Zielen über 5 Ziele hinaus verringert.\n[ Braumeister : Beim Einsatz von 'Chistoß' sind Vermeidungsmechaniken weiterhin aktiv ]" }
entries[460491] = { ["name"] = "R.A.N.H.O.L.E.N.", ["text"] = "Sofort\nVerstärkt die Bild- und Tonausgabe der Einheit, sodass Ihr einer Unterhaltung in der Nähe lauschen könnt." }
entries[460493] = { ["name"] = "Scan auf Waffensicherheitskonformität", ["text"] = "40 Meter Reichweite\nWirken in 2 sek.\nFührt an einem nicht besetzten Schredder eine diagnostische Überprüfung durch.\n\nStellt Energie wieder her." }
entries[460495] = { ["name"] = "Daten hochladen", ["text"] = "30 Meter Reichweite\nWirken in 2 sek.\nSynchronisiert Daten mit einem weiteren Überwachungs-V.O.G.E.L.\n\nStellt Systemintegrität wieder her." }
entries[460496] = { ["name"] = "Schnellfeuer", ["text"] = "40 Meter Reichweite\nSofort\nBenötigt Distanzwaffe\nFeuert eine Serie von 7 Schüssen auf Euer Ziel ab und fügt ihm so im Verlauf von 2 Sek. [7 * (60.5% der Angriffskraft)%] körperlichen Schaden zu. Kann aus der Bewegung eingesetzt werden. [ Optimierung : 'Schnellfeuer' sorgt dafür, dass Euer nächster 'Gezielter Schuss' 20% schneller eingesetzt wird ]\nJeder Schuss erzeugt 2 Fokus." }
entries[460497] = { ["name"] = "Systemintegritätsmetrik" }
entries[460499] = { ["name"] = "Blutige Klinge", ["text"] = "Sofort\nDas Parieren eines Angriffs gewährt Euch eine Aufladung von 'Blutige Klinge', wodurch Eure Stärke 15 Sek. lang um 0.5% erhöht wird, bis zu einem Maximum von 4.0%.\n\nBei 8 Stapeln verbraucht Euer nächstes Parieren alle Aufladungen, um einen 'Herzstoß' mit einer Effektivität von 300% zu entfesseln und Eure Stärke 6 Sek. lang um 10% zu erhöhen." }
entries[460500] = { ["name"] = "Blutige Klinge", ["text"] = "Sofort\nDas Parieren eines Angriffs gewährt Euch eine Aufladung von 'Blutige Klinge', wodurch Eure Stärke 15 Sek. lang um 0.5% erhöht wird, bis zu einem Maximum von 4.0%.\n\nBei 8 Stapeln verbraucht Euer nächstes Parieren alle Aufladungen, um einen 'Herzstoß' mit einer Effektivität von 300% zu entfesseln und Eure Stärke 6 Sek. lang um 10% zu erhöhen." }
entries[460501] = { ["name"] = "Herzstoß", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nSchlägt das Ziel sowie einen weiteren Gegner in der Nähe sofort, verursacht (171.016% der Angriffskraft) körperlichen Schaden und verringert die Bewegungsgeschwindigkeit der Gegner 8 Sek. lang um 20%. [ Herzstoß : Erzeugt 5 zusätzliche Runenmacht. ] [ Herzbrecher : Erzeugt außerdem 2 Runenmacht pro zusätzlich getroffenem Gegner ]" }
entries[460518] = { ["name"] = "Eimerrüstung", ["text"] = "Sofort\nDer Zaubernde rüstet einen sehr robusten Eimer aus, wodurch einige erlittene Angriffe das Ziel für 3 Sek. betäuben.\n(Procchance: 15%, 6s Abklingzeit)" }
entries[460519] = { ["name"] = "Eimerrüstung", ["text"] = "100 Meter Reichweite\nSofort\nBetäubt einen Gegner, sodass er sich 3 Sek. lang weder bewegen noch angreifen kann." }
entries[460520] = { ["name"] = "Tarneimer", ["text"] = "Sofort\nDer Zaubernde versteckt sich unter einem Eimer und erlangt \"Verstohlenheit\"." }
entries[460521] = { ["name"] = "Eingefangenes Sternenlicht", ["text"] = "Wenn Ihr Schaden erleidet und Eure Gesundheit unter 30% fällt, erlangt Ihr für 8 Sek. einen Schild, der bis zu 720790 Schaden absorbiert.\n\nDieser Effekt kann nur einmal alle 4 Min. ausgelöst werden, was sich aber pro einzigartiger Farbe an gesockelten algarischen Edelsteinen um 12 Sek. verringert." }
